        <button type="button" class="filter-btn" data-filter="shade" aria-pressed="false">Likes shade</button>
      </div>
    </fieldset>

    <p class="status" id="status" role="status" aria-live="polite"></p>

    <ul class="grid" id="grid">
      <li class="card" data-light="sun">
        <span class="tag sun">Loves sun</span>
        <h2 id="basil-name">Basil</h2>
        <p>A fragrant herb for warm, bright spots. Great with tomatoes and pasta.</p>
        <button type="button" class="plant-btn" aria-pressed="false" aria-describedby="basil-name">Mark as planted</button>
      </li>

      <li class="card" data-light="sun">
        <span class="tag sun">Loves sun</span>
        <h2 id="sunflower-name">Sunflower</h2>
        <p>Tall and cheerful, it follows the light and wants a full day of it.</p>
        <button type="button" class="plant-btn" aria-pressed="false" aria-describedby="sunflower-name">Mark as planted</button>
      </li>

      <li class="card" data-light="shade">
        <span class="tag shade">Likes shade</span>
        <h2 id="mint-name">Mint</h2>
        <p>A hardy herb that is happy in cooler, shadier corners. Keep it in a pot so it does not spread.</p>
        <button type="button" class="plant-btn" aria-pressed="false" aria-describedby="mint-name">Mark as planted</button>
      </li>
    </ul>
  </main>

<script>
(function () {
  var cards = Array.prototype.slice.call(document.querySelectorAll('.card'));
  var filterButtons = Array.prototype.slice.call(document.querySelectorAll('.filter-btn'));
  var status = document.getElementById('status');
  var currentFilter = 'all';

  var filterNames = { all: 'all plants', sun: 'plants that love sun', shade: 'plants that like shade' };

  function updateStatus() {
    var visible = cards.filter(function (c) { return !c.hidden; }).length;
    var planted = cards.filter(function (c) {
      return c.querySelector('.plant-btn').getAttribute('aria-pressed') === 'true';
    }).length;
    status.textContent = 'Showing ' + visible + ' of ' + cards.length + ' (' + filterNames[currentFilter] + '). ' +
      planted + ' marked as planted.';
  }

  function applyFilter(filter) {
    currentFilter = filter;
    cards.forEach(function (card) {
      card.hidden = !(filter === 'all' || card.getAttribute('data-light') === filter);
    });
    filterButtons.forEach(function (btn) {
      btn.setAttribute('aria-pressed', String(btn.getAttribute('data-filter') === filter));
    });
    updateStatus();
  }

  filterButtons.forEach(function (btn) {
    btn.addEventListener('click', function () {
      applyFilter(btn.getAttribute('data-filter'));
    });
  });

  cards.forEach(function (card) {
    var btn = card.querySelector('.plant-btn');
    btn.addEventListener('click', function () {
      var nowPlanted = btn.getAttribute('aria-pressed') !== 'true';
      btn.setAttribute('aria-pressed', String(nowPlanted));
      btn.textContent = nowPlanted ? 'Planted' : 'Mark as planted';
      card.classList.toggle('is-planted', nowPlanted);
      updateStatus();
    });
  });

  applyFilter('all');
})();
</script>
